//! Reproducible Friendly Captcha CPU benchmark with independent proof checking.
//!
//! Run with: cargo +nightly-2026-11-03 run --locked --profile test
//!   --package challenge-protocols --example friendly_bench

use std::time::Instant;

use anyhow::{Context, ensure};
use base64::{Engine as _, engine::general_purpose::STANDARD};
use challenge_protocols::classic_pow;
use num_traits::ToPrimitive;
use serde_json::json;

fn main() -> anyhow::Result<()> {
    // The 128-byte hashed message is generated by padding the 32-byte v1
    // header; index and counter occupy its final eight bytes.
    for (difficulty, solution_count) in [(96_u8, 16_u8), (128, 16), (152, 4)] {
        let mut header = [0_u8; 32];
        header[12] = 1;
        header[14] = solution_count;
        header[15] = difficulty;
        let puzzle = format!("benchmark.{}", STANDARD.encode(header));
        let mut expected = None;
        for (implementation, workers) in [("safe", 1_usize), ("auto", 1), ("auto", 2), ("auto", 4)]
        {
            let started = Instant::now();
            let result = classic_pow::solve(
                "friendlycaptcha",
                json!({"puzzle": puzzle}),
                Some(implementation),
                workers,
            )?;
            let wall_ms = started.elapsed().as_secs_f64() * 1000.0;
            let attempts = result.answer["attempted_nonces"]
                .as_u64()
                .context("missing attempted_nonces")?;
            let response = result.answer["response"]
                .as_str()
                .context("missing native Friendly Captcha response")?;
            let proof = response
                .split('.')
                .nth(2)
                .context("missing base64 Friendly Captcha proof")?;
            let proof_bytes = STANDARD.decode(proof)?;
            ensure!(
                classic_pow::verify_friendlycaptcha_v1(&puzzle, &proof_bytes)?,
                "benchmark returned invalid proof"
            );
            if let Some((reference_proof, reference_attempts)) = &expected {
                ensure!(
                    &proof_bytes == reference_proof && attempts == *reference_attempts,
                    "parallel or accelerated result disagrees with safe reference"
                );
            } else {
                expected = Some((proof_bytes, attempts));
            }
            let rate = attempts
                .to_f64()
                .context("candidate count cannot be converted to f64")?
                * 1000.0
                / result.solve_ms;
            println!(
                "{}",
                json!({
                    "difficulty": difficulty,
                    "solution_count": solution_count,
                    "implementation": implementation,
                    "workers": workers,
                    "attempted_nonces": attempts,
                    "solve_ms": result.solve_ms,
                    "wall_ms": wall_ms,
                    "candidates_per_second": rate,
                    "kernel": result.implementation,
                })
            );
        }
    }
    Ok(())
}
